#include "cryptoutils.h"
static void matmul(int a[2][2],int b[2][2],int o[2][2]){for(int i=0;i<2;i++)for(int j=0;j<2;j++)o[i][j]=cu_mod(a[i][0]*b[0][j]+a[i][1]*b[1][j],26);}
int main(void){char ptxt[32],ctxt[32];int P[2][2],C[2][2],Pinv[2][2],K[2][2];cu_readline("Enter 4 plaintext letters forming two digraphs (e.g. HELP): ",ptxt,sizeof ptxt);cu_readline("Enter their 4 ciphertext letters in the same order: ",ctxt,sizeof ctxt);char p[16],c[16];cu_letters(ptxt,p,0);cu_letters(ctxt,c,0);if(strlen(p)<4||strlen(c)<4){puts("Need four letters in each input.");return 1;}P[0][0]=p[0]-'A';P[1][0]=p[1]-'A';P[0][1]=p[2]-'A';P[1][1]=p[3]-'A';C[0][0]=c[0]-'A';C[1][0]=c[1]-'A';C[0][1]=c[2]-'A';C[1][1]=c[3]-'A';int det=cu_mod(P[0][0]*P[1][1]-P[0][1]*P[1][0],26),iv=cu_inv(det,26);if(iv<0){printf("Plaintext matrix is not invertible mod 26 (det=%d). Choose different known plaintext blocks.\n",det);return 1;}Pinv[0][0]=cu_mod(iv*P[1][1],26);Pinv[0][1]=cu_mod(-iv*P[0][1],26);Pinv[1][0]=cu_mod(-iv*P[1][0],26);Pinv[1][1]=cu_mod(iv*P[0][0],26);matmul(C,Pinv,K);printf("Recovered key matrix modulo 26: [[%d,%d],[%d,%d]]\n",K[0][0],K[0][1],K[1][0],K[1][1]);puts("Formula: C = K P, so K = C P^-1 (mod 26). Only works when det(P) has an inverse modulo 26.");return 0;}
